import * as T from 'three';
import {makeActor} from './art.js';
import {eatingBeat} from './acting.js';
import {RUN_CYCLE_DISTANCE} from './motion.js';
const $=s=>document.querySelector(s),stage=$('#stage'),canvas=$('#canvas'),renderer=new T.WebGLRenderer({canvas,antialias:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFShadowMap;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;renderer.outputColorSpace=T.SRGBColorSpace;
const scene=new T.Scene();scene.background=new T.Color(0xdfece5);scene.fog=new T.Fog(0xdfece5,15,30);scene.add(new T.HemisphereLight(0xe6f6ff,0xb7a98e,1.65));const sun=new T.DirectionalLight(0xfff5e9,2.15);sun.position.set(-4,7,5);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-4;sun.shadow.camera.right=4;sun.shadow.camera.top=6;sun.shadow.camera.bottom=-4;sun.shadow.normalBias=.03;sun.shadow.bias=-.0004;scene.add(sun);
const floor=new T.Mesh(new T.PlaneGeometry(200,200),new T.MeshStandardMaterial({color:0xc9ded0,roughness:1}));floor.rotation.x=-Math.PI/2;floor.receiveShadow=true;scene.add(floor);const ring=new T.Mesh(new T.RingGeometry(1.72,1.74,80),new T.MeshBasicMaterial({color:0x98b4a5,side:T.DoubleSide}));ring.rotation.x=-Math.PI/2;ring.position.y=.006;scene.add(ring);
let actor=makeActor('suit');const cast=new Map([['suit',actor]]);scene.add(actor.root);actor.setGear('poop','none');actor.food.visible=false;const camera=new T.PerspectiveCamera(36,1,.05,60),clock={last:performance.now(),getDelta(){const now=performance.now(),dt=(now-this.last)/1000;this.last=now;return dt;}};let yaw=0,targetYaw=0,pitch=.04,pose='stand',drag=null,elapsed=0,paused=false;
let growthPower=0;document.querySelectorAll('[data-power]').forEach(b=>b.onclick=()=>{growthPower=Number(b.dataset.power);actor.setPower(growthPower);document.querySelectorAll('[data-power]').forEach(o=>o.setAttribute('aria-pressed',String(o===b)));});
const viewNames={front:'正面 · 全身',side:'侧面 · 关节与轮廓',back:'背面 · 发型与服装',threequarter:'三分之四 · 立体外形'};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{targetYaw={front:0,side:Math.PI/2,back:Math.PI,threequarter:.53}[b.dataset.view];pitch=.04;$('#view-name').textContent=viewNames[b.dataset.view];document.querySelectorAll('[data-view]').forEach(o=>o.setAttribute('aria-pressed',String(o===b)));});
document.querySelectorAll('[data-pose]').forEach(b=>b.onclick=()=>{pose=b.dataset.pose;elapsed=0;actor.setGear('poop',pose==='sit'?'white':'none');actor.food.visible=['eat','sit'].includes(pose);document.querySelectorAll('[data-pose]').forEach(o=>o.setAttribute('aria-pressed',String(o===b)));});
$('#pose-pause').onclick=()=>{paused=!paused;$('#pose-pause').textContent=paused?'继续动作':'暂停动作';$('#pose-pause').setAttribute('aria-pressed',String(paused));};
$('#pose-time').oninput=e=>{paused=true;elapsed=Number(e.target.value)/100;$('#pose-pause').textContent='继续动作';$('#pose-pause').setAttribute('aria-pressed','true');};
document.querySelectorAll('[data-style]').forEach(b=>b.onclick=()=>{scene.remove(actor.root);if(!cast.has(b.dataset.style))cast.set(b.dataset.style,makeActor(b.dataset.style));actor=cast.get(b.dataset.style);scene.add(actor.root);actor.setPower(growthPower);actor.setGear('poop',pose==='sit'?'white':'none');actor.food.visible=['eat','sit'].includes(pose);document.querySelectorAll('[data-style]').forEach(o=>o.setAttribute('aria-pressed',String(o===b)));});
canvas.onpointerdown=e=>{drag={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(!drag)return;targetYaw-=(e.clientX-drag.x)*.008;pitch=T.MathUtils.clamp(pitch+(e.clientY-drag.y)*.004,-.2,.55);drag.x=e.clientX;drag.y=e.clientY;};for(const e of['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(e,()=>drag=null);
function resize(){renderer.setSize(stage.clientWidth,stage.clientHeight,false);camera.aspect=stage.clientWidth/stage.clientHeight;camera.updateProjectionMatrix();}new ResizeObserver(resize).observe(stage);resize();
$('#facts').textContent='同一人物：进食长肚 · 臀部变圆 · 前冲与屈膝落地';
function frame(){requestAnimationFrame(frame);const dt=Math.min(.05,clock.getDelta());if(!paused){elapsed+=dt;$('#pose-time').value=Math.floor(elapsed%.85*100);}actor.step=elapsed*4.4/RUN_CYCLE_DISTANCE*Math.PI*2;yaw+=Math.atan2(Math.sin(targetYaw-yaw),Math.cos(targetYaw-yaw))*(1-Math.exp(-dt*10));const flying=pose==='fly',lookY=flying?1.7:1.87,lookZ=flying?.15:0,d=(flying?9.5:8.25)*Math.max(1,(flying?1:.82)/camera.aspect);camera.position.set(Math.sin(yaw)*d,lookY+.13+pitch*6,lookZ+Math.cos(yaw)*d);camera.lookAt(0,lookY,lookZ);actor.update(dt,elapsed,{seated:pose==='sit',moving:pose==='walk'?1:0,anticipation:pose==='anticipate'?Math.sin(Math.PI*(elapsed%.85)/.85)**2:0,landing:pose==='land'?Math.sin(Math.PI*(elapsed%.85)/.85)**2:0,...eatingBeat(pose==='eat'||pose==='sit'?elapsed%.85:-1),fly:flying?1:0,cheer:pose==='cheer'?1:0});canvas.dataset.growth=actor.growth.toFixed(2);renderer.render(scene,camera);}frame();
